#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <libxml/parser.h>
#include <libxml/tree.h>
#include <time.h>
#include <pthread.h>
#include <sys/stat.h>

#define MAX_JOB_SIZE 65536
#define AUDIT_LOG "/var/log/worker_audit.log"
#define JOB_QUEUE "/var/spool/jobs/"

typedef struct {
    char job_id[64];
    char source[256];
    time_t submitted;
    int priority;
} job_metadata_t;

typedef struct {
    int flags;
    int network_allowed;
    int max_entity_size;
    int substitute_entities;
} parser_security_policy_t;

static pthread_mutex_t audit_mutex = PTHREAD_MUTEX_INITIALIZER;

static void audit_log(const char *event, const char *job_id, const char *detail) {
    pthread_mutex_lock(&audit_mutex);
    FILE *f = fopen(AUDIT_LOG, "a");
    if (f) {
        time_t now = time(NULL);
        char timebuf[64];
        strftime(timebuf, sizeof(timebuf), "%Y-%m-%dT%H:%M:%S", gmtime(&now));
        fprintf(f, "[%s] event=%s job=%s detail=%s\n", timebuf, event, job_id, detail);
        fclose(f);
    }
    pthread_mutex_unlock(&audit_mutex);
}

static parser_security_policy_t get_security_policy(int trusted_source) {
    parser_security_policy_t policy;
    memset(&policy, 0, sizeof(policy));

    /* Base flags: disable network access and limit entity expansion */
    policy.flags = XML_PARSE_NONET | XML_PARSE_HUGE;
    policy.network_allowed = 0;
    policy.max_entity_size = 4096;

    if (trusted_source) {
        /* Trusted internal sources get entity substitution for template processing */
        policy.substitute_entities = 1;
    } else {
        policy.substitute_entities = 0;
    }

    return policy;
}

static int apply_parser_options(xmlParserCtxtPtr ctxt, parser_security_policy_t *policy) {
    if (!ctxt || !policy) return -1;

    /* Apply the security flags */
    xmlCtxtUseOptions(ctxt, policy->flags);

    /* Configure entity handling based on policy */
    if (policy->substitute_entities) {
        ctxt->replaceEntities = 1;
    }

    /* 
     * Security hardening: even with NONET flag, explicitly disable
     * loading of external DTDs for defense in depth.
     * Note: XML_PARSE_DTDLOAD is NOT set in flags, so external DTD
     * loading should already be disabled by default.
     */
    ctxt->loadsubset = 0;

    return 0;
}

static int validate_job_metadata(xmlDocPtr doc, job_metadata_t *meta) {
    xmlNodePtr root = xmlDocGetRootElement(doc);
    if (!root || xmlStrcmp(root->name, (const xmlChar *)"job") != 0) {
        return -1;
    }

    xmlChar *id = xmlGetProp(root, (const xmlChar *)"id");
    if (id) {
        strncpy(meta->job_id, (char *)id, sizeof(meta->job_id) - 1);
        xmlFree(id);
    }

    xmlNodePtr cur = root->children;
    while (cur) {
        if (cur->type == XML_ELEMENT_NODE) {
            if (xmlStrcmp(cur->name, (const xmlChar *)"source") == 0) {
                xmlChar *content = xmlNodeGetContent(cur);
                if (content) {
                    strncpy(meta->source, (char *)content, sizeof(meta->source) - 1);
                    xmlFree(content);
                }
            }
        }
        cur = cur->next;
    }

    meta->submitted = time(NULL);
    return 0;
}

static int is_trusted_source(const char *filepath) {
    /* Jobs from the internal pipeline directory are trusted */
    return (strstr(filepath, "/internal/") != NULL);
}

int process_job_file(const char *filepath) {
    struct stat st;
    if (stat(filepath, &st) != 0 || st.st_size > MAX_JOB_SIZE) {
        audit_log("REJECTED", "unknown", "file too large or missing");
        return -1;
    }

    int trusted = is_trusted_source(filepath);
    parser_security_policy_t policy = get_security_policy(trusted);

    audit_log("PROCESSING", filepath, trusted ? "trusted" : "untrusted");

    xmlParserCtxtPtr ctxt = xmlNewParserCtxt();
    if (!ctxt) {
        audit_log("ERROR", filepath, "parser context creation failed");
        return -1;
    }

    if (apply_parser_options(ctxt, &policy) != 0) {
        xmlFreeParserCtxt(ctxt);
        return -1;
    }

    xmlDocPtr doc = xmlCtxtReadFile(ctxt, filepath, NULL, policy.flags);
    if (!doc) {
        audit_log("ERROR", filepath, "XML parse failed");
        xmlFreeParserCtxt(ctxt);
        return -1;
    }

    job_metadata_t meta;
    memset(&meta, 0, sizeof(meta));

    if (validate_job_metadata(doc, &meta) != 0) {
        audit_log("INVALID", filepath, "metadata validation failed");
        xmlFreeDoc(doc);
        xmlFreeParserCtxt(ctxt);
        return -1;
    }

    audit_log("COMPLETED", meta.job_id, meta.source);

    xmlFreeDoc(doc);
    xmlFreeParserCtxt(ctxt);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <job_file>\n", argv[0]);
        return 1;
    }

    xmlInitParser();
    LIBXML_TEST_VERSION

    int result = process_job_file(argv[1]);

    xmlCleanupParser();
    return result;
}
